const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define southern Ethiopia geometry (south of 8°N)
  const southernEthiopia = ee.Geometry.Polygon([
    [[33.0, 3.0], [48.0, 3.0], [48.0, 8.0], [33.0, 8.0], [33.0, 3.0]]
  ]);

  // 2. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Get 2021 Oct-Nov data
  const rain2021 = chirps
    .filterDate('2021-10-01', '2021-12-01')
    .filterBounds(southernEthiopia);

  const count2021 = rain2021.size().getInfo();
  console.log(`2021 Images: ${count2021}`);

  if (count2021 === 0) {
    console.log('No data for 2021 period');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate total rainfall for 2021
  const total2021 = rain2021.sum();

  const stats2021 = total2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernEthiopia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const rainfall2021 = stats2021.precipitation;

  if (rainfall2021 === null || rainfall2021 === undefined) {
    console.log('Failed to calculate 2021 rainfall');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Get long-term average (2000-2013)
  let yearlyTotals = [];

  for (let year = 2000; year <= 2013; year++) {
    const rainYear = chirps
      .filterDate(`${year}-10-01`, `${year}-12-01`)
      .filterBounds(southernEthiopia);

    const countYear = rainYear.size().getInfo();

    if (countYear === 0) {
      console.log(`No data for ${year}`);
      continue;
    }

    const totalYear = rainYear.sum();
    const statsYear = totalYear.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: southernEthiopia,
      scale: 5000,
      maxPixels: 1e9
    }).getInfo();

    const rainfallYear = statsYear.precipitation;

    if (rainfallYear !== null && rainfallYear !== undefined) {
      yearlyTotals.push(rainfallYear);
    }
  }

  if (yearlyTotals.length === 0) {
    console.log('No valid long-term data');
    console.log('<answer>C1</answer>');
    return;
  }

  const longTermAvg = yearlyTotals.reduce((a, b) => a + b, 0) / yearlyTotals.length;

  console.log(`2021 Oct-Nov rainfall: ${rainfall2021.toFixed(2)} mm`);
  console.log(`Long-term avg (2000-2013): ${longTermAvg.toFixed(2)} mm`);
  console.log(`Years with data: ${yearlyTotals.length}/14`);

  // 6. Final answer
  if (rainfall2021 < longTermAvg) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
